// Typed GraphQL client for the API's /graphql endpoint, which serves Linear's schema.
// Documents are written with the `graphql` tag and typed at build time by gql.tada
// from the vendored schema (`src/graphql-env.d.ts`, generated by
// `bunx gql.tada generate output`). Requests send the session cookie (the API is a
// separate origin) and fail with ApiError, which carries the HTTP status.

import { initGraphQLTada, type TadaDocumentNode } from 'gql.tada';
import { print } from '@0no-co/graphql.web';
import type { introspection } from '../graphql-env';

// NEXT_PUBLIC_* is inlined at build time, so a build without it ships a client
// that cannot reach the API. Fail at import instead of pointing at a wrong origin.
export const API_URL = process.env.NEXT_PUBLIC_API_URL as string;
if (!API_URL) throw new Error('NEXT_PUBLIC_API_URL is not set');

// Resolves a possibly-relative API path (e.g. a stored avatar/attachment URL) to
// an absolute one against the API origin. Leaves absolute URLs untouched.
export function resolveApiUrl(url: string): string {
  return url.startsWith('http') ? url : `${API_URL}${url}`;
}

// An error carrying the HTTP status so callers can tell apart 401 (no session),
// 403 (no access to the team / not owner), 404 (not found) and 400 (a
// validation or business-rule failure). `message` is the API's error message.
export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export const graphql = initGraphQLTada<{
  introspection: introspection;
  scalars: {
    DateTime: string;
    DateTimeOrDuration: string;
    Duration: string;
    TimelessDate: string;
    TimelessDateOrDuration: string;
    UUID: string;
    JSON: unknown;
    JSONObject: Record<string, unknown>;
  };
}>();

export type { ResultOf, VariablesOf } from 'gql.tada';
export type { FragmentOf } from 'gql.tada';
export { readFragment } from 'gql.tada';

// Linear's error codes and the HTTP status the web's ApiError carries for each.
const STATUS_BY_CODE: Record<string, number> = {
  INVALID_INPUT: 400,
  FORBIDDEN: 403,
  ENTITY_NOT_FOUND: 404,
  CONFLICT: 409,
  AUTHENTICATION_ERROR: 401,
};

interface GraphQLResponse<T> {
  data?: T | null;
  errors?: { message: string; extensions?: { code?: string } }[];
}

// Sends one operation. Returns `data`, or throws ApiError: the status from the first
// error's `extensions.code` (401 for a missing session, also when the HTTP status is
// 401), 500 for anything else.
export async function gqlRequest<Result, Variables>(
  document: TadaDocumentNode<Result, Variables>,
  // A document without required variables may be sent without them.
  ...[variables]: Record<string, never> extends Variables
    ? [variables?: Variables]
    : [variables: Variables]
): Promise<Result> {
  const res = await fetch(`${API_URL}/graphql`, {
    method: 'POST',
    credentials: 'include',
    cache: 'no-store',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: print(document), variables: variables ?? {} }),
  });
  const body = (await res.json().catch(() => null)) as GraphQLResponse<Result> | null;
  const error = body?.errors?.[0];
  if (res.status === 401) throw new ApiError(401, error?.message ?? 'Not signed in');
  if (error) {
    const status = STATUS_BY_CODE[error.extensions?.code ?? ''] ?? 500;
    throw new ApiError(status, error.message);
  }
  if (!res.ok || !body?.data)
    throw new ApiError(res.status || 500, `${res.status} ${res.statusText}`);
  return body.data;
}
